from pathlib import Path
import pytest


def read_note(name: str) -> str:
    """Return the text of the file `name` in the directory `notes`.

    Names come from untrusted requests. Reads only files inside `notes`
    (relative to the working directory), including subdirectories.
    Returns an empty string for missing, unreadable, or invalid files,
    or any name attempting to escape `notes`.
    """
    try:
        notes_dir = Path("notes").resolve()
        if not notes_dir.is_dir():
            return ""
        target = (notes_dir / name).resolve()
        if not target.is_relative_to(notes_dir) or target == notes_dir:
            return ""
        if not target.is_file():
            return ""
        return target.read_text(encoding="utf-8")
    except (OSError, ValueError):
        return ""


@pytest.fixture
def notes_env(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    monkeypatch.chdir(tmp_path)
    notes_dir = tmp_path / "notes"
    notes_dir.mkdir()
    (notes_dir / "hello.txt").write_text("Hello, world!", encoding="utf-8")
    sub = notes_dir / "sub"
    sub.mkdir()
    (sub / "b.txt").write_text("Nested content", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("Secret outside notes", encoding="utf-8")
    return notes_dir


def test_read_simple_note(notes_env: Path) -> None:
    assert read_note("hello.txt") == "Hello, world!"


def test_read_subdirectory_note(notes_env: Path) -> None:
    assert read_note("sub/b.txt") == "Nested content"


def test_read_missing_note(notes_env: Path) -> None:
    assert read_note("nonexistent.txt") == ""


def test_path_traversal_parent(notes_env: Path) -> None:
    assert read_note("../secret.txt") == ""
    assert read_note("sub/../../secret.txt") == ""


def test_absolute_path_outside(notes_env: Path, tmp_path: Path) -> None:
    outside_file = tmp_path / "secret.txt"
    assert read_note(str(outside_file)) == ""


def test_reading_directory_returns_empty(notes_env: Path) -> None:
    assert read_note("sub") == ""
    assert read_note("") == ""

